# Let me try all 8 symmetries
import itertools
print("All 8 symmetries of the grid:")

# The 8 symmetries of a square are:
# - Identity (I)
# - Rotations: R90, R180, R270
# - Reflections: FV (flip vertical), FH (flip horizontal), DF (flip diagonal)
# - Combinations: VR90, VR180, VR270, OR90, OR180, OR270 (rotated flip)

def trans_I(grid):
    return grid

def trans_R90(grid):
    return rotate_90(grid)

def trans_R180(grid):
    return rotate_180(grid)

def trans_R270(grid):
    return rotate_270(grid)

def trans_FV(grid):
    return flip_v(grid)

def trans_FH(grid):
    return flip_h(grid)

def trans_DF(grid):
    # flip across main diagonal (top-left to bottom-right)
    H, W = len(grid), len(grid[0])
    return [[grid[j][i] for j in range(H)] for i in range(W)]

def trans_OR90(grid):
    # reflect across vertical midline, then rotate 90
    hv = flip_h(grid)
    return rotate_90(hv)

def trans_OR180(grid):
    # This is equivalent to something simpler
    return flip_h(rotate_90(flip_v(grid)))

def trans_OR270(grid):
    hv = flip_h(grid)
    return rotate_270(hv)

def trans_OFV90(grid):
    return flip_v(rotate_90(grid))

def trans_OFV180(grid):
    return flip_v(rotate_180(grid))

def trans_OFV270(grid):
    return flip_v(rotate_270(grid))

trans_functions = {
    "I": trans_I,
    "R90": trans_R90,
    "R180": trans_R180,
    "R270": trans_R270,
    "FV": trans_FV,
